mapper.select:
SELECT oi.id, oi.order_id, oi.product_sku_id, oi.product_id, oi.sku_code, oi.product_name, COALESCE(ps.spec_attributes, oi.sku_name) AS sku_name, COALESCE(ps.sku_image, oi.product_image) AS product_image, oi.original_price, ps.original_price AS market_price, oi.quantity, oi.apportioned_discount, oi.final_price FROM order_items oi LEFT JOIN product_skus ps ON oi.product_sku_id = ps.id WHERE oi.order_id IN
#{orderId}
AND oi.is_deleted = 0 ORDER BY oi.order_id , oi.created_time
